// Parsear un mensaje de texto libre de WhatsApp
// Tu app manda: { texto: '...el mensaje copiado...', telefono: '...', nombre: '...' }

const body = $input.first().json;
const texto = (body.texto || '').trim();
const t = texto.toLowerCase();

if (!texto) {
  return [{ json: { error: 'Texto vacío', ok: false } }];
}

const patronCantidad = /(\d+)\s*(?:x|de|uds?|unidades?|piezas?)?\s*([a-záéíóúñ0-9\s\-\/]{3,40})/gi;
const itemsEncontrados = [];
let match;
while ((match = patronCantidad.exec(texto)) !== null) {
  const cantidad = parseInt(match[1]);
  const producto = match[2].trim().replace(/\s+/g, ' ');
  if (cantidad > 0 && cantidad < 10000 && producto.length > 2) {
    itemsEncontrados.push({ cantidad, descripcion: producto });
  }
}

let intencion = 'consulta';
if (t.match(/quiero|pedir|necesito|manda|envía|dame|pedido|comprar/)) intencion = 'pedido';
else if (t.match(/estado|donde|cuando|llega|mi pedido|ped-/)) intencion = 'estado_pedido';
else if (t.match(/precio|cuánto|cuesta|vale|coste/)) intencion = 'precio';
else if (t.match(/stock|quedan|hay|disponible|tienes/)) intencion = 'stock';

const regexPedido = /PED-\d+/i;
const pedidoMencionado = (texto.match(regexPedido) || [])[0] || null;

return [{ json: {
  ok: true,
  intencion,
  texto_original: texto,
  telefono: body.telefono || '',
  nombre: body.nombre || '',
  items_detectados: itemsEncontrados,
  pedido_mencionado: pedidoMencionado,
  timestamp: new Date().toISOString()
}}];

// Crear borrador de pedido con los items detectados automáticamente
const d = $input.first().json;
const numeroPedido = 'PED-' + Date.now();

const items = d.items_detectados.map(item => ({
  referencia: 'PENDIENTE',
  nombre: item.descripcion,
  cantidad: item.cantidad,
  precio_unit: 0,
  subtotal: 0
}));

return [{ json: {
  numero_pedido: numeroPedido,
  telefono: d.telefono,
  nombre_cliente: d.nombre || 'Por identificar',
  items_json: JSON.stringify(items),
  total: 0,
  estado: 'borrador',
  fecha_pedido: d.timestamp,
  canal: 'whatsapp_manual',
  notas: 'Parseado automáticamente. Revisar precios y referencias. Texto original: ' + d.texto_original
}}];

